from form_function_common import *

def add_b21(b):
    start=len(b.questions);code='B2.1'
    def q(key,title,stem,*parts,**kw):b.add(code,key,title,stem,parts=list(parts),**kw)
    items=[('diffusion','Crossing the bilayer','Which substance can cross a phospholipid bilayer readily by simple diffusion?','A small non-polar oxygen molecule.',['A sodium ion with its associated water molecules.','A large folded protein.','A long charged DNA molecule.'],'Small non-polar molecules dissolve in the hydrophobic interior and diffuse across without a transport protein.'),('osmosis','The direction of water movement','Two solutions of the same non-dissociating solute are at equal temperature and equal initial hydrostatic pressure. A membrane is permeable to water but impermeable to the solute. One side has a lower solute concentration. What is the initial net water movement?','Towards the side with the higher solute concentration.',['Towards the side with the lower solute concentration.','Only solute moves across this membrane.','There can be no water movement through a membrane.'],'Under the stated conditions, net osmosis is from the more dilute solution towards the more concentrated solution.'),('protein-location','A membrane-associated protein','Which description best distinguishes a peripheral protein from a transmembrane protein?','A peripheral protein associates with a membrane surface rather than spanning the bilayer.',['A peripheral protein must be made of carbohydrate.','A transmembrane protein cannot contact water.','A peripheral protein must have two fatty acid tails.'],'Peripheral proteins bind to a surface or to other membrane proteins; a transmembrane protein extends through the bilayer.'),('pump','Moving against a gradient','A transport protein hydrolyses ATP while moving a solute from lower to higher concentration. Which process is occurring?','Active transport.',['Simple diffusion.','Osmosis.','Passive transport through an open channel.'],'ATP hydrolysis can provide energy to move a solute against its concentration gradient.')]
    for key,title,stem,ans,wrong,why in items:b.add(code,'B21-'+key,title,stem,options=[ans]+wrong,reason=why)
    q('B21-membrane-map','Interpreting a membrane model','The illustration represents a membrane separating extracellular fluid from cytoplasm. X, Y and Z identify different parts of the model.',P('Identify X, Y and Z.',A('X: a membrane-spanning channel protein.'),A('Y: a hydrophilic phospholipid head.'),A('Z: a hydrophobic fatty acid tail region.')),P('Explain how the structure permits selective passage of a particular ion.',R('The channel provides a hydrophilic route through the otherwise hydrophobic barrier.'),R('Its pore properties determine which ions can pass; opening a channel does not make the whole bilayer freely permeable to every solute.')),diagram=membrane_svg())
    q('B21-surface-carbohydrate','An asymmetric cell surface','Short carbohydrate chains are attached to proteins and lipids on the extracellular face of a cell membrane.',P('State the names of these two types of membrane molecule and one function of their exposed carbohydrate chains.',A('Glycoproteins and glycolipids.'),A('Accept cell recognition, receptor interactions or cell adhesion.')),P('Explain why a drawing showing all carbohydrate chains projecting into the cytoplasm would misrepresent the usual cell-surface arrangement.',A('These chains normally project towards the extracellular side; membrane structure is asymmetric.')),P('Distinguish the fluid and mosaic features of the model.',A('Fluid refers to lateral movement of many components within a leaflet; mosaic refers to different proteins and other components embedded in or associated with the bilayer.')))
    q('B21-carrier-data','A transport rate that approaches a limit','The table gives constructed initial uptake data for the same solute in cells at a fixed temperature. Uptake occurs down its concentration gradient.'+table(['External concentration / arbitrary units','Uptake rate / arbitrary units'],[(1,12),(2,21),(4,32),(8,40),(16,44)]),P('Describe the pattern and suggest a transport mechanism consistent with it.',A('Uptake increases but approaches a maximum.'),R('Facilitated diffusion using a finite number of transport proteins can become limited when most proteins are occupied.')),P('Explain why these observations do not establish that ATP is directly used by the transporter.',A('The solute moves down its gradient and saturation can occur in passive protein-mediated transport; ATP dependence needs a separate test.')),P('State one variable that should be controlled when comparing the rates.',A('Accept cell number or membrane area, temperature, assay duration or initial internal solute concentration.')),kind='data-based')
    initial=2.40;final=2.64
    q('B21-osmosis-data','A change in tissue mass','In a constructed investigation, a blotted plant-tissue cylinder has an initial mass of 2.40 g and a final mass of 2.64 g after immersion in a solution. The tissue is blotted consistently before both weighings.',P('Calculate the percentage mass change.',M(m(r'\%\ \mathrm{change}=(\mathrm{final}-\mathrm{initial})/\mathrm{initial}\times100')+'.'),A(u((final-initial)/initial*100,r'\%')+' increase.')),P('Explain a mechanism consistent with the mass increase.',R('Net water enters cells by osmosis across selectively permeable membranes, increasing tissue mass.')),P('Explain one limitation of treating mass change as a direct measurement of water entering cells.',A('Water may remain on surfaces or in extracellular spaces, and solutes may also move; consistent blotting and appropriate controls reduce but do not remove these uncertainties.')),kind='data-based')
    q('B21-fluidity','Maintaining membrane movement in the cold','Two membranes have phospholipid tails of the same length. One has a larger proportion of cis-unsaturated tails.',P('Predict which remains more fluid at a low temperature and explain.',A('The membrane with more cis-unsaturated tails.'),R('The bends reduce close packing and weaken collective attractions between neighbouring tails.')),P('Explain why the phrase fluid does not imply that the bilayer has no barrier function.',A('Components can move laterally while the continuous hydrophobic interior still restricts passage of many polar or charged solutes.')),level='ahl')
    q('B21-cholesterol','A temperature-dependent membrane effect','Cholesterol is positioned among the phospholipids of an animal cell membrane.',P('Explain how cholesterol can restrain fluidity at a relatively high temperature but help prevent solidification at a low temperature.',R('At higher temperature, cholesterol restricts some phospholipid tail movement.'),R('At lower temperature, it interrupts tight packing of neighbouring tails, helping maintain membrane fluidity.')),P('Explain why a claim that cholesterol always increases membrane fluidity is incomplete.',A('Its effect depends on temperature and the surrounding lipid composition.')),level='ahl')
    q('B21-endocytosis','Taking extracellular material into a cell','A membrane surrounds a small extracellular particle and forms an intracellular vesicle.',P('Name the general process and describe the membrane change.',A('Endocytosis.'),A('The plasma membrane invaginates or extends around material, then separates to form a membrane-bounded vesicle.')),P('Explain why the enclosed material is not initially free in the cytosol.',R('It remains inside the vesicle lumen, separated from cytosol by the vesicle membrane.')),level='ahl')
    q('B21-exocytosis','Releasing a secreted product','A vesicle containing a soluble product approaches the plasma membrane and fuses with it.',P('Name the process and trace the destination of the product and vesicle membrane.',A('Exocytosis releases the lumen contents to the extracellular space.'),A('The vesicle membrane becomes part of the plasma membrane at fusion.')),P('Explain why a carbohydrate chain facing the vesicle lumen can become exposed at the cell surface.',R('The lumen-facing membrane surface becomes the extracellular-facing surface; fusion preserves membrane orientation.')),level='ahl')
    q('B21-gating','Two ways to control an ion channel','Channel P opens when a signalling molecule binds. Channel Q opens after a change in membrane potential.',P('Classify the two channels and explain how opening changes ion movement.',A('P is ligand-gated and Q is voltage-gated.'),R('Opening creates a pathway for the selected ion to move down its electrochemical gradient.')),P('Explain why channel opening is not equivalent to pumping ions against a gradient.',A('A gated channel controls access to a passive route; it does not directly use ATP to force ions uphill.')),level='ahl')
    cycles=120
    q('B21-sodium-pump','An unequal exchange','For each ATP hydrolysed, a sodium-potassium pump transfers three sodium ions out of a cell and two potassium ions into the cell.',P('For 120 complete cycles, calculate the numbers of each ion transported and the net outward movement of positive charge.',A(f'{3*cycles} sodium ions move out and {2*cycles} potassium ions move in.'),M('Each cycle moves one net positive charge outward.'),A(f'The net outward movement is {cycles} elementary positive charges.')),P('Explain how the pump contributes to concentration gradients.',R('It uses ATP to maintain relatively low intracellular sodium and relatively high intracellular potassium against their gradients.')),level='ahl')
    q('B21-cotransport','Using a gradient created elsewhere','An intestinal epithelial cell takes up glucose together with sodium through a cotransporter on its lumen-facing membrane. A separate sodium-potassium pump maintains low intracellular sodium.',P('Explain how glucose can accumulate even when its concentration is already higher inside the cell.',R('Sodium moves inward down its electrochemical gradient through the cotransporter.'),R('The coupled process provides the energy for glucose to move against its own concentration gradient.')),P('Distinguish the ATP dependence of the cotransporter from that of the sodium-potassium pump.',A('The pump directly hydrolyses ATP; the cotransporter depends indirectly on ATP because the pump maintains the sodium gradient.')),level='ahl')
    q('B21-adhesion','Keeping a sheet of cells together','A sheet of epithelial cells expresses membrane proteins that bind corresponding molecules on neighbouring cells.',P('State the general role of these proteins and explain why membrane anchoring matters.',A('They are cell-adhesion molecules that help maintain contact between cells.'),R('Anchoring at the cell surface links recognition and attachment to the positions of whole cells within the tissue.')),P('Predict one possible effect of greatly reducing their abundance.',A('The tissue may lose cohesion or organized cell arrangement; a specific named junction is not required.')),level='ahl')
    assert len(b.questions)-start==16

def add_b22(b):
    start=len(b.questions);code='B2.2'
    def q(key,title,stem,*parts,**kw):b.add(code,key,title,stem,parts=list(parts),**kw)
    b.add(code,'B22-organelle','What counts as an organelle?','Using the course convention, which is an organelle involved directly in protein synthesis?',options=['A ribosome.','The entire cytoplasm.','A cellulose cell wall.','The complete cytoskeleton.'],reason='A ribosome is a specialized subcellular structure with a particular function; not every organelle must be bounded by a membrane.')
    b.add(code,'B22-nuclear-separation','Separated stages of gene expression','Which is an advantage of separating the nucleus from the cytoplasm in a eukaryotic cell?',options=['RNA can be processed before it encounters cytoplasmic ribosomes.','DNA must leave the nucleus before every protein is made.','The nucleus prevents all exchange with the cytoplasm.','Translation of all cellular proteins occurs inside the nucleus.'],reason='Compartmentalization separates nuclear transcription and RNA processing from cytoplasmic translation.')
    q('B22-fractionation','Interpreting a cell fraction','A constructed fractionation experiment separates a cell homogenate. A low-speed pellet contains most of a DNA-associated marker. A later pellet, collected at greater speed, contains most of a mitochondrial marker.',P('Identify the likely major structures in the two pellets and explain why separation can occur.',A('The earlier pellet is enriched in nuclei; the later pellet is enriched in mitochondria.'),R('Organelles differ in size and density, affecting how readily they sediment under the applied conditions.')),P('Explain why enriched does not necessarily mean pure.',A('Other structures or fragments can sediment with the target organelles; marker assays and microscopy are needed to assess contamination.')),P('State one preparation condition that helps preserve organelles.',A('Accept a cold preparation to reduce enzymatic damage, or a suitable buffered isotonic medium to limit osmotic disruption.')),kind='data-based')
    q('B22-lysosome','Keeping digestive activity in a compartment','A lysosome contains hydrolytic enzymes and has an acidic lumen.',P('Explain two advantages of the membrane-bounded compartment.',R('It can maintain a local environment suited to the digestive enzymes.'),R('It confines enzymes and substrates, reducing unwanted contact with other cell components.')),P('Explain why the claim that every lysosomal enzyme must be completely inactive outside the lysosome is too strong.',A('Compartmentalization reduces unwanted activity but does not imply absolute inactivity in every other environment; enzyme activity depends on conditions.')))
    q('B22-phagocytic-vacuole','Digesting an engulfed particle','A phagocytic cell encloses a bacterium in a membrane-bounded vacuole that later receives digestive enzymes.',P('Explain how compartmentalization assists digestion.',A('The bacterium and digestive enzymes are brought together in a restricted volume.'),R('The surrounding membrane separates the digestive contents from the rest of the cytoplasm.')),P('Explain why engulfment alone is not equivalent to complete digestion.',A('Engulfment encloses the particle; enzymes must subsequently break its molecules into smaller products.')))
    q('B22-local-conditions','Different reactions in the same cell','Two cellular processes require incompatible pH conditions. A cell places them in separate membrane-bounded compartments.',P('Explain how this arrangement can increase the range of processes the cell performs.',R('Each compartment can maintain conditions appropriate to its enzymes.'),R('The membranes limit mixing of the incompatible contents, allowing both processes to operate within one cell.')),P('Give one further advantage of concentrating a pathway’s enzymes and substrates in a compartment.',A('It can increase the frequency of productive encounters or reduce diffusion distance between successive steps.')))
    q('B22-mitochondrial-map','Mitochondrial compartments','The illustration represents a mitochondrion, with regions A, B and C indicated by labels.',P('Identify A, B and the membrane feature at C.',A('A: matrix.'),A('B: outer membrane.'),A('C: a fold of the inner membrane, a crista.')),P('Explain a functional advantage of the folded inner membrane.',R('Folding provides a large membrane area for the proteins involved in electron transport and ATP synthesis within a small organelle volume.')),level='ahl',diagram=organelle_svg('mitochondrion'))
    q('B22-mitochondrial-separation','Why two mitochondrial membranes matter','A mitochondrion has an intermembrane space between its outer and inner membranes and a matrix inside the inner membrane.',P('Explain why the intermembrane space must not be confused with the matrix.',A('They are physically separate compartments on opposite sides of the inner membrane.'),R('Their different conditions can support a proton gradient across the inner membrane.')),P('Predict the consequence of making the inner membrane freely permeable to protons.',R('The proton gradient would dissipate, reducing the ability to drive ATP synthesis through ATP synthase.')),level='ahl')
    q('B22-chloroplast-map','Chloroplast compartments','The illustration represents a chloroplast. The labels point to region A, envelope membrane B and structure C.',P('Identify A and C.',A('A: stroma.'),A('C: a stack of thylakoids, a granum.')),P('Explain why thylakoid membranes and stroma are suitable locations for different reactions.',A('Thylakoid membranes contain light-absorbing pigments and membrane proteins used in the light-dependent reactions.'),A('The stroma contains enzymes used in carbon fixation and related reactions.')),level='ahl',diagram=organelle_svg('chloroplast'))
    q('B22-thylakoid-lumen','A small internal space','Thylakoids are flattened membrane sacs enclosing a lumen.',P('Explain why a closed thylakoid membrane can support an energy-transducing gradient.',R('The membrane separates the lumen from the stroma, allowing proton concentrations to differ.'),R('Proton movement through ATP synthase can couple this difference to ATP production.')),P('Distinguish the lumen from the stroma.',A('The lumen is inside a thylakoid sac; the stroma surrounds the thylakoids within the chloroplast envelope.')),level='ahl')
    q('B22-nuclear-pores','Controlled exchange with the nucleus','A protein needed in the nucleus is synthesized in the cytoplasm, while an RNA molecule made in the nucleus must reach the cytoplasm.',P('Identify the route used for exchange and explain why the nuclear envelope is not an absolute barrier.',A('Nuclear pores provide routes through the envelope.'),R('They allow regulated movement of selected molecules, including import of proteins and export of RNA-containing complexes.')),P('State one advantage of regulating this exchange.',A('It helps ensure that appropriate molecules enter or leave at the required stage, for example processed RNA reaching the cytoplasm.')),level='ahl')
    q('B22-envelope-division','Reorganizing a compartment during division','During a typical human cell mitosis, the nuclear envelope breaks down and later re-forms around the separated chromosome sets.',P('Explain how breakdown assists chromosome segregation.',R('It permits spindle microtubules access to chromosomes so they can be moved to opposite poles.')),P('Explain the consequence of re-forming envelopes around the separated sets.',A('Each future daughter cell receives a nucleus enclosing a chromosome set and regains nuclear-cytoplasmic compartmentalization.')),level='ahl')
    q('B22-ribosome-destinations','The same ribosome, different destination','A cell synthesizes a cytosolic enzyme and a protein destined for secretion.',P('Compare the typical locations of ribosomes synthesizing these proteins.',A('The cytosolic enzyme is typically synthesized on free ribosomes.'),A('The secreted protein is synthesized on ribosomes associated with rough endoplasmic reticulum, with the growing product entering the secretory pathway.')),P('Explain why this does not require two fundamentally different types of ribosome.',A('Ribosomes can be recruited to the endoplasmic reticulum when the protein being synthesized carries an appropriate targeting signal.')),level='ahl')
    q('B22-rough-er','A cell specialized for secretion','A secretory cell has abundant rough endoplasmic reticulum.',P('Link this feature to protein production and compartmentalization.',A('The associated ribosomes synthesize proteins entering the secretory pathway.'),R('The endoplasmic-reticulum lumen provides a compartment for folding and processing before onward transport.')),P('State how these products next reach the Golgi apparatus.',A('They are transported in membrane vesicles that move from the endoplasmic reticulum to the Golgi.')),level='ahl')
    q('B22-golgi-data','Following a labelled secretory protein','In a constructed pulse-labelling experiment, newly synthesized protein is detected first in rough endoplasmic reticulum, later in Golgi compartments and finally outside the cell.',P('Explain a pathway consistent with these observations.',A('Protein enters the endoplasmic reticulum during synthesis and is transferred in vesicles to the Golgi.'),A('The Golgi processes and sorts it into secretory vesicles that fuse with the plasma membrane.')),P('Explain why detecting label in a compartment does not by itself show the protein was synthesized there.',R('The labelled protein may have been transported from an earlier compartment; location at one time is not proof of synthesis at that location.')),level='ahl',kind='data-based')
    q('B22-clathrin','A coat around a budding vesicle','A membrane region containing selected cargo acquires a clathrin coat as a vesicle buds.',P('Explain the role of the coat and distinguish it from the transported cargo.',A('Clathrin helps organize membrane curvature and vesicle formation.'),A('The coat is a structural assembly on the cytosolic surface; cargo is selected material being transported in or with the vesicle.')),P('Explain why a vesicle must retain a closed membrane after separation.',R('A closed membrane preserves the separation between its lumen and the cytosol and retains the transported contents.')),level='ahl')
    assert len(b.questions)-start==16

def add_b23(b):
    start=len(b.questions);code='B2.3'
    def q(key,title,stem,*parts,**kw):b.add(code,key,title,stem,parts=list(parts),**kw)
    items=[('toti','The broadest developmental potential','Which description corresponds to a totipotent cell?','It can give rise to all cell types needed for an entire organism, including extraembryonic tissues where applicable.',['It can produce only one mature blood-cell type.','It can never divide.','It is any cell containing a nucleus.'],'Totipotency includes the developmental potential needed to form the whole organism and supporting extraembryonic tissues.'),('pluri','Many body-cell fates','A stem cell can form all major body-cell types but cannot by itself form a complete organism with its supporting extraembryonic tissues. What is its potency?','Pluripotent.',['Totipotent.','Multipotent only within one tissue lineage.','Fully differentiated.'],'Pluripotency is broad body-cell potential without the whole-organism potential of a totipotent cell.'),('multi','A restricted family of cell types','A stem cell produces several related blood-cell types but not neurons or liver cells. Which term best describes it?','Multipotent.',['Totipotent.','A mature erythrocyte.','A non-living cell fragment.'],'A multipotent stem cell generates a restricted range of related cell types.'),('renewal','What makes a stem cell useful?','Which pair of properties defines a stem cell’s role in tissue maintenance?','Self-renewal and the capacity to differentiate.',['Permanent inability to divide and absence of DNA.','Production of only extracellular matrix and no cells.','A large size and no membrane.'],'Stem cells can maintain their own population while producing descendants that specialize.')]
    for key,title,stem,ans,wrong,why in items:b.add(code,'B23-'+key,title,stem,options=[ans]+wrong,reason=why)
    q('B23-gradients','Different fates in one embryo','Two cells in the same early embryo experience different concentrations of a signalling molecule. They later develop different structures and functions.',P('Explain how a concentration gradient can contribute to differentiation.',A('Cells at different positions receive different signal strengths.'),R('Different patterns of gene expression can be activated, producing different proteins and cellular functions.')),P('Explain why different cell types do not normally require different complete genomes.',A('Cells can retain the same genetic information while expressing different subsets of genes.')))
    q('B23-adult-niches','Maintaining replacement cells','Adult tissues can contain niches that support stem cells.',P('Give two examples of adult stem-cell locations and relate each to tissue maintenance.',A('Bone marrow contains stem cells that give rise to blood-cell lineages.'),A('Intestinal crypts contain stem cells that replenish the intestinal epithelium; accept another valid adult niche with a correct role.')),P('Explain why the surrounding niche matters.',R('Local signals and interactions help regulate survival, division and differentiation rather than leaving these processes uncontrolled.')))
    q('B23-cube-scaling','A cell-size model','Model two cells as cubes with side lengths 10.0 μm and 20.0 μm. For a cube, surface area is '+m('6l^2')+' and volume is '+m('l^3')+'.',P('Calculate the surface-area-to-volume ratio of each model.',M('Divide '+m('6l^2')+' by '+m('l^3')+' to obtain '+m('6/l')+'.'),A('Small cell: '+u(.6,r'\mu m^{-1}')+'; large cell: '+u(.3,r'\mu m^{-1}')+'.')),P('Explain one transport consequence of increasing size without changing shape.',R('There is less membrane area per unit volume, so exchange across the surface may become less able to meet the needs of the interior.')),P('State one limitation of the cube model.',A('Real cells may be flattened, elongated or folded, and exchange also depends on membrane proteins and gradients; one appropriate limitation is sufficient.')),kind='data-based')
    q('B23-cell-dimensions','Comparing very different cell shapes','A constructed size comparison gives an erythrocyte diameter of 8.0 μm and the length of a root-hair cell extension as 1.20 mm.',P('Calculate the ratio of extension length to erythrocyte diameter.',M('Convert 1.20 mm to 1200 μm.'),A('The ratio is 150:1.')),P('Explain why this ratio is not the ratio of the two cell volumes.',R('A single linear dimension does not determine volume when shapes and other dimensions differ.')),P('Relate the elongated extension to a function of the root-hair cell.',A('It increases contact with the surrounding soil and the surface available for uptake of water and mineral ions.')),kind='data-based')
    q('B23-flattening','Shortening the path through a cell','A cell specialized for rapid diffusion has a flattened shape.',P('Explain how flattening can improve exchange.',R('It provides a large surface area relative to its volume.'),R('It shortens diffusion distances between the cell surface and much of the cell interior.')),P('Explain why being thin does not remove the need for a concentration gradient.',A('Net diffusion still requires a difference in concentration or chemical potential; a short path affects rate but does not determine direction.')),level='ahl')
    q('B23-microvilli','Increasing membrane area','An absorptive epithelial cell has many microvilli on its exposed surface.',P('Explain how microvilli contribute to uptake.',A('They increase the membrane surface area without a comparable increase in cell volume.'),R('The extra membrane can accommodate more transport proteins or enzymes involved in uptake.')),P('Distinguish microvilli from internal membrane invaginations.',A('Microvilli project outwards; invaginations fold the membrane inwards, but both can increase membrane area.')),level='ahl')
    q('B23-type-one','A thin alveolar cell','Type I pneumocytes form much of the air-facing surface of mammalian alveoli.',P('Link their shape to gas exchange.',A('They are thin and flattened.'),R('This minimizes the distance for diffusion between alveolar air and the adjacent blood.')),P('Explain why the structure of the neighbouring capillary also matters.',R('Gas must cross the capillary endothelium as well; a thin, closely associated capillary barrier helps keep the total diffusion path short.')),level='ahl')
    q('B23-type-two','A secretory alveolar cell','Type II pneumocytes contain vesicles that release surfactant onto the alveolar surface.',P('Relate the vesicles to the cell’s specialized function.',A('They package and release the surfactant secretion by exocytosis.')),P('Explain how surfactant assists the alveolus.',R('It reduces surface tension at the moist air interface.'),R('This helps prevent collapse and reduces the work required to expand the alveolus.')),level='ahl')
    q('B23-muscle-cells','Two specialized muscle-cell types','Compare a typical skeletal muscle fibre with a cardiac muscle cell.',P('State two structural differences.',A('A skeletal muscle fibre is long and typically multinucleate, whereas a cardiac muscle cell usually has one central nucleus.'),A('Cardiac muscle cells are branched and connected to neighbouring cells; skeletal fibres are long, largely unbranched units.')),P('Relate a cardiac feature to coordinated function.',R('Connections between cardiac cells allow them to act as a coordinated tissue, supporting rhythmic contraction of the heart.')),level='ahl')
    q('B23-human-sperm','A motile human gamete','A human sperm cell has a flagellum, a mitochondria-rich middle region and an acrosome at the head.',P('Link each feature to its function.',A('The flagellum produces movement.'),A('Mitochondria supply ATP for movement and other cellular processes.'),A('The acrosome contains components that assist interaction with and penetration of the egg’s surrounding layers.')),P('Explain one benefit of its streamlined shape and small cytoplasmic volume.',R('They reduce the volume and resistance that must be moved, supporting motility.')),level='ahl')
    q('B23-human-ovum','A human egg cell','A human egg cell is much larger than a sperm cell and contains substantial cytoplasm with organelles and stored molecules.',P('Explain how its contents support early development.',A('It supplies organelles and molecules needed for the first stages of development before the embryo is fully self-sustaining.')),P('Explain the significance of the haploid nucleus in both human gametes.',R('Fusion combines one chromosome set from each gamete to restore the diploid chromosome number.')),P('State why comparing size alone does not establish that one gamete contributes more genetic information in its nuclear chromosomes.',A('Each haploid nucleus contributes one chromosome set regardless of the very different cell volumes.')),level='ahl')
    count=300;r=.050;length=1.00;base=40.0;extra=count*2*math.pi*r*length
    q('B23-area-model','A quantitative microvillus model','In a constructed model, an absorptive surface has area 40.0 μm² before adding 300 cylindrical microvilli. Each has radius 0.0500 μm and length 1.00 μm. The tip replaces an equal basal patch, so count only the added lateral area '+m(r'2\pi rl')+' for each projection.',P('Calculate the new surface area and the factor by which area has increased.',M('Additional area = '+m(r'300\times2\pi\times0.0500\times1.00')+' μm².'),A(u(base+extra,r'\mu m^2')+'; area factor '+u((base+extra)/base)+'.')),P('Explain why the rate of uptake need not increase by exactly this factor.',R('Transport can also be limited by carrier density, substrate concentration, gradients or energy supply; area alone does not determine rate.')),level='ahl',kind='data-based')
    assert len(b.questions)-start==16
